import{_ as e,o as l,c as s,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-07-25 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-07-25 :: Ceph Performance Meeting","date":"2019-07-25T00:00:00.000Z","updated":"2019-07-26T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","RocksDB","会议纪要"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-07-25_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-07-25_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780459816000}'),r={name:"posts/2019/2019-07-25_-_-_Ceph_Performance_Meeting.md"};function i(n,t,p,a,u,_){return l(),s("div",null,[...t[0]||(t[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph分布式存储项目性能讨论</p><p><strong>会议时间</strong>： 2019年7月25日</p><p><strong>参会人员</strong>： Eric、Bret、Josh、Casey等</p><p><strong>会议内容</strong>：</p><p><strong>1. RGW数据副本删除请求</strong></p><ul><li>讨论了Rados Gateway（RGW）中删除数据副本的功能。</li><li>该功能将基于当前正在合并的代码实现，并可能回溯到Nautilus版本。</li></ul><p><strong>2. 双缓存机制</strong></p><ul><li>讨论了双缓存机制的优化，基于Eric正在合并的代码实现。</li><li>讨论了将该功能回溯到Nautilus版本的可能性。</li></ul><p><strong>3. 格式变更</strong></p><ul><li>由于格式变更，用户可能需要重新安装OSDS（Object Storage Device Server）。</li><li>讨论了回溯该变更到Nautilus版本的可能性。</li></ul><p><strong>4. Pull Requests</strong></p><ul><li>讨论了当前待处理的Pull Requests，包括缓存、trim行为、双重缓存避免等。</li></ul><p><strong>5. RocksDB优化</strong></p><ul><li>讨论了RocksDB的优化，包括读取前优化、ARM范围优化、自动调整读取前优化等。</li></ul><p><strong>6. RocksDB版本选择</strong></p><ul><li>讨论了选择RocksDB版本的问题，包括Luminous版本5.9、Nautilus版本5.17.2等。</li></ul><p><strong>7. RocksDB回溯</strong></p><ul><li>讨论了将RocksDB优化回溯到Luminous版本的可能性。</li></ul><p><strong>8. RocksDB性能优化</strong></p><ul><li>讨论了RocksDB的性能优化，包括连接线程、读取前优化、ARM范围优化等。</li></ul><p><strong>9. 其他议题</strong></p><ul><li>讨论了其他议题，包括快速垃圾回收、BlueFS碎片化问题等。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>进一步讨论双缓存机制回溯到Nautilus版本的可能性。</li><li>审查并合并待处理的Pull Requests。</li><li>选择合适的RocksDB版本，并进行回溯和优化。</li><li>评估其他议题的解决方案。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些关键的技术术语，如RGW、OSDS、RocksDB、ARM范围、读取前优化等。</li><li>会议讨论了多个技术细节，需要进一步研究和验证。</li></ul>',27)])])}const R=e(r,[["render",i]]);export{c as __pageData,R as default};
